[Form]
public class ISDAppIntgDMFDataVizualization extends FormRun
{
    RefRecId startRecId;
    RefRecId endRecId;
    DMFDefinitionGroupExecution defGroupExecutionTable;
    [FormObservable]
    boolean shouldShowErrorInformationColumn = true;
    FormDataSource  curFormDS;

}

/// <summary>
/// Get DMF entity name
/// </summary>
/// <returns>DMFEntityName</returns>
public DMFEntityName entityName()
{
    return defGroupExecutionTable.Entity;
}

/// <summary>
/// If the form is viewed directly it would result in error stating "Active Buffer Required"
/// </summary>
/// <remarks>
/// This form records is viewed for staging tables.
/// </remarks>
/// <exception cref="Exception::Error">
/// An exception is thrown is viewed directly.
/// </exception>
public void init()
{

    container                   con;
    int                         i;
    FormDateTimeControl         timeControl;

    if (element.form().dataSource(1).table() == tableNum(Common))
    {
        throw error(strfmt("@SYS25516", element.name()));
    }

    defGroupExecutionTable = element.args().record();

    if (defGroupExecutionTable && defGroupExecutionTable.Company != curExt())
    {
        DMFUtil::switchToLegalEntity(defGroupExecutionTable.Company);
    }

    con = element.args().parmObject().parmCon();

    element.parmStartEndRecIds(defGroupExecutionTable.StartRecId, defGroupExecutionTable.EndRecId);

    super();


    for (i = 1; i <=  conLen(con); i++)
    {
        timeControl = element.control(conPeek(con, i));
        timeControl.timezonePreference(2);
    }
    if(defGroupExecutionTable.TargetStatus==DMFBatchJobStatus::Error)
    {
        info("@DMF:DMFInfoIfStagingContainsErrorRecords");
    }

}

/// <summary>
/// Parameter to containerized start and end record id
/// </summary>
/// <param name = "_startRecId">Start recid</param>
/// <param name = "_endRecId">End recid</param>
/// <returns>container</returns>
public container parmStartEndRecIds(RefRecId _startRecId = startRecId, RefRecId _endRecId = endRecId)
{
    startRecId  = _startRecId;
    endRecId    = _endRecId;

    return [startRecId, endRecId];
}

/// <summary>
/// Get table buffer
/// </summary>
/// <returns>DMFDefinitionGroupExecution</returns>
public DMFDefinitionGroupExecution dmfDefinitionGroupExecution()
{
    return defGroupExecutionTable;
}

/// <summary>
/// Select or deselect records
/// </summary>
private void updateSelection(NoYes _set)
{
    DMFEntity           dmfEntity;
    Common              staging, curStaging;
    SysDictTable        sysDictTable;
    FieldId             selectedFieldId;
    FieldId             recIdFieldId;
    int                 getPos = curFormDS.getPosition();

    dmfEntity = DMFEntity::find(defGroupExecutionTable.Entity);

    if(dmfEntity.EntityType != DMFEntityTypes::CompositEntity)
    {
        sysDictTable = new SysDictTable(tableName2id(dmfEntity.EntityTable));

        if(sysDictTable)
        {
            staging     = sysDictTable.makeRecord();
            curStaging  = sysDictTable.makeRecord();

            selectedFieldId         = fieldName2id(tableName2id(dmfEntity.EntityTable), fieldStr(DMFEntityBaseTable, IsSelected));
            recIdFieldId            = fieldName2id(tableName2id(dmfEntity.EntityTable), fieldStr(DMFEntityBaseTable, RecId));

            MultiSelectionHelper selectionHelper = MultiSelectionHelper::construct();

            selectionHelper.parmDataSource(curFormDS);
            curStaging  = selectionHelper.getFirst();

            ttsbegin;
            while (curStaging)
            {
                select forupdate staging
                    where staging.(recIdFieldId) == curStaging.RecId
                        && staging.(selectedFieldId) != _set;

                if (staging)
                {
                    staging.(selectedFieldId) = _set;
                    staging.update();
                }

                curStaging = selectionHelper.getNext();
            }
            ttscommit;

            curFormDS.research(getPos);
        }
    }

}

/// <summary>
/// Display option
/// </summary>
/// <param name = "_record">Record id</param>
/// <param name = "_options">form display option</param>
public void displayOption(Common _record, FormRowDisplayOption _options)
{
    FormControl             formControl;
    DMFStagingValidationLog validationLog;
    FormDesign              formDesign;

    if (_record)
    {
        formDesign = element.design();
        while select StagingColumnName from validationLog
            where validationLog.StagingRecId == _record.RecId
               && validationLog.SourceTarget == DMFSourceTarget::Source
               && validationLog.StagingColumnName
        {
            formControl = formDesign.controlName('SysGen_'+ validationLog.StagingColumnName);
            if (formControl)
            {
                _options.backColor(WINAPI::rgbCon2int([255, 0, 0]));
                _options.affectedElementsByControl(formControl.id());
            }
        }
    }

    super(_record, _options);
}

/// <summary>
/// Get log from staging table
/// </summary>
/// <param name = "_staging"></param>
/// <returns>Log text</returns>
public display SysInfoLogStr logText(Common _staging)
{
    #define.NewLine('\n')
    ;
    DMFStagingValidationLog stagingValidationLog;
    str                     logStr;
    SysInfoLogStr           logText;
    FieldId                 execFieldId,
                            defGroupFieldId;

    execFieldId = fieldName2Id(_staging.TableId,identifierStr(ExecutionId));
    defGroupFieldId = fieldName2Id(_staging.TableId,identifierStr(DefinitionGroup));

    while select ErrorMessage, RecId from stagingValidationLog 
        order by stagingValidationLog.RecId desc
        where stagingValidationLog.DefinitionGroupName == _staging.(defGroupFieldId)
           && stagingValidationLog.ExecutionId == _staging.(execFieldId)
           && stagingValidationLog.StagingRecId == _staging.RecId
           && stagingValidationLog.EntityName   == defGroupExecutionTable.Entity
    {
        if (shouldShowErrorInformationColumn)
        {
            if (logText)
            {
                logText += #NewLine;
            }
            logStr = stagingValidationLog.ErrorMessage;
        }
        else
        {
            logStr = #NewLine + stagingValidationLog.ErrorMessage;
        }

        logText += logStr;
    }
    if(!logText)
    {
        logText = "No Errors";
    }
    return logText;
}

/// <summary>
/// Datasource active method
/// </summary>
/// <returns>Integer</returns>
public int active()
{
    int ret;

    ret = super();

    curFormDS = this;

    return ret;
}

/// <summary>
/// Select records in staging
/// </summary>
public void clicked()
{
    super();

    element.updateSelection(true);
}

/// <summary>
/// Deselect records in staging
/// </summary>
public void clicked()
{
    super();

    element.updateSelection(false);
}
